@namespace sv_8611cb83f9ca468fa431191d94033155.Components.Pages.Apply

<div class="step-content">
    <h2>Personal Information</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    <div class="form-row">
        <div class="form-group">
            <label>Full Name *</label>
            <input type="text" value="@Model.FullName"
                   @onchange="e => Model = Model with { FullName = e.Value?.ToString() ?? "" }" />
        </div>
        <div class="form-group">
            <label>Email *</label>
            <input type="email" value="@Model.Email"
                   @onchange="e => Model = Model with { Email = e.Value?.ToString() ?? "" }" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Phone *</label>
            <input type="tel" value="@Model.Phone"
                   @onchange="e => Model = Model with { Phone = e.Value?.ToString() ?? "" }" />
        </div>
        <div class="form-group">
            <label>Address *</label>
            <input type="text" value="@Model.Address"
                   @onchange="e => Model = Model with { Address = e.Value?.ToString() ?? "" }" />
        </div>
    </div>

    <div class="step-actions">
        <button class="btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<PersonalInfoModel> ModelChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private string? ErrorMessage;
    private bool IsValidating;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(Model.FullName))
        {
            ErrorMessage = "Full name is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Model.Email))
        {
            ErrorMessage = "Email is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Model.Phone))
        {
            ErrorMessage = "Phone is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Model.Address))
        {
            ErrorMessage = "Address is required.";
            return;
        }

        IsValidating = true;
        try
        {
            var emailValid = await ValidateEmail(Model.Email);
            if (!emailValid)
            {
                ErrorMessage = "Please enter a valid email address.";
                return;
            }

            await ModelChanged.InvokeAsync(Model);
            await OnNext.InvokeAsync();
        }
        finally
        {
            IsValidating = false;
        }
    }
}

