@page "/apply"
@namespace sv_8611cb83f9ca468fa431191d94033155.Components.Pages.Apply
@using sv_8611cb83f9ca468fa431191d94033155.Services
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep"
                   CompletedSteps="@completedSteps"
                   OnStepSelected="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Model="@personalInfo"
                              ModelChanged="m => personalInfo = m"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="NextStep" />
            break;
        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             EntriesChanged="e => workEntries = e"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 2:
            <ReferencesStep References="@references"
                            ReferencesChanged="r => references = r"
                            OnNext="NextStep"
                            OnBack="PreviousStep" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             CoverLetterChanged="c => coverLetter = c"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 4:
            <ReviewStep Personal="@personalInfo"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        OnEditSection="GoToStep"
                        OnBack="PreviousStep"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int currentStep;
    private HashSet<int> completedSteps = new();

    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };
    private string coverLetter = "";

    private void NextStep()
    {
        completedSteps.Add(currentStep);
        currentStep++;
    }

    private void PreviousStep()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            new PersonalInfo(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address),
            new WorkHistory(workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description
            )).ToList()),
            references.Where(r => !string.IsNullOrWhiteSpace(r.Name))
                .Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            coverLetter
        );

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

.apply-container {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

.apply-container h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: none;
    border: none;
    cursor: default;
    padding: 0.5rem;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step .step-number {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    margin-bottom: 0.25rem;
    border: 2px solid #ccc;
    color: #999;
    background: #fff;
}

.step.current .step-number {
    border-color: #4361ee;
    background: #4361ee;
    color: #fff;
}

.step.completed .step-number {
    border-color: #2ec4b6;
    background: #2ec4b6;
    color: #fff;
}

.step .step-label {
    font-size: 0.75rem;
    color: #999;
    text-align: center;
}

.step.current .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step.completed .step-label {
    color: #2ec4b6;
}

.step-connector {
    width: 30px;
    height: 2px;
    background: #ccc;
    margin-bottom: 1.25rem;
}

.step-connector.completed {
    background: #2ec4b6;
}

.checkmark {
    font-size: 1rem;
}

/* Step Content */
.step-content {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

.step-description {
    color: #666;
    margin-bottom: 1rem;
}

/* Form Elements */
.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
    margin-bottom: 1rem;
}

.form-group {
    display: flex;
    flex-direction: column;
}

.form-group.full-width {
    grid-column: 1 / -1;
}

.form-group label {
    font-size: 0.85rem;
    font-weight: 600;
    margin-bottom: 0.25rem;
    color: #333;
}

.form-group input,
.form-group textarea {
    padding: 0.6rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 2px rgba(67, 97, 238, 0.1);
}

.checkbox-label {
    flex-direction: row !important;
    align-items: center;
    gap: 0.5rem;
    margin-top: 0.5rem;
    font-weight: normal !important;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Cards */
.work-entry-card,
.reference-card {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.work-entry-header,
.reference-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry-header h4,
.reference-header h4 {
    margin: 0;
    color: #333;
}

/* Buttons */
.btn-primary {
    background: #4361ee;
    color: #fff;
    border: none;
    padding: 0.7rem 1.5rem;
    border-radius: 4px;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-primary:hover:not(:disabled) {
    background: #3651d4;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-secondary {
    background: #fff;
    color: #4361ee;
    border: 1px solid #4361ee;
    padding: 0.7rem 1.5rem;
    border-radius: 4px;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-secondary:hover {
    background: #f0f3ff;
}

.btn-remove {
    background: none;
    border: 1px solid #e74c3c;
    color: #e74c3c;
    padding: 0.3rem 0.75rem;
    border-radius: 4px;
    font-size: 0.8rem;
    cursor: pointer;
}

.btn-remove:hover {
    background: #fdeaea;
}

.btn-link {
    background: none;
    border: none;
    color: #4361ee;
    cursor: pointer;
    font-size: 0.9rem;
    text-decoration: underline;
    padding: 0;
}

.btn-submit {
    padding: 0.8rem 2rem;
    font-size: 1.05rem;
}

/* Step Actions */
.step-actions {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #eee;
}

/* Character Count */
.character-count {
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.25rem;
}

.character-count.warning {
    color: #e74c3c;
}

/* Error Message */
.error-message {
    background: #fdeaea;
    border: 1px solid #e74c3c;
    color: #c0392b;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

/* Review Step */
.review-section {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

.review-section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-section-header h3 {
    margin: 0;
    font-size: 1.1rem;
    color: #1a1a2e;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.4rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 600;
    color: #555;
}

.review-section dd {
    margin: 0;
}

.review-work-entry,
.review-reference {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.review-work-entry:last-child,
.review-reference:last-child {
    border-bottom: none;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f9f9f9;
    padding: 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
    max-height: 200px;
    overflow-y: auto;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 2rem;
}

.confirmation h3 {
    color: #2ec4b6;
    font-size: 1.5rem;
}

@media (max-width: 600px) {
    .form-row {
        grid-template-columns: 1fr;
    }

    .step-indicator {
        gap: 0.1rem;
    }

    .step {
        min-width: 60px;
        padding: 0.25rem;
    }

    .step .step-label {
        font-size: 0.65rem;
    }

    .step-connector {
        width: 15px;
    }
}

