@namespace sv_8611cb83f9ca468fa431191d94033155.Components.Pages.Apply

<div class="work-entry-card">
    <div class="work-entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Company Name *</label>
            <input type="text" value="@Entry.Company" @onchange="OnCompanyChanged" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" value="@Entry.Title" @onchange="OnTitleChanged" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@FormatDate(Entry.StartDate)" @onchange="OnStartDateChanged" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@FormatNullableDate(Entry.EndDate)"
                   disabled="@IsCurrent"
                   @onchange="OnEndDateChanged" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="ToggleCurrent" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group full-width">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description" @onchange="OnDescriptionChanged"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.IsCurrent;

    private static string FormatDate(DateTime date) => date.ToString("yyyy-MM-dd");
    private static string FormatNullableDate(DateTime? date) => date?.ToString("yyyy-MM-dd") ?? string.Empty;
    private static string Str(object? value) => value?.ToString() ?? string.Empty;

    private Task OnCompanyChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { Company = Str(e.Value) });

    private Task OnTitleChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { Title = Str(e.Value) });

    private Task OnStartDateChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { StartDate = DateTime.TryParse(Str(e.Value), out var d) ? d : Entry.StartDate });

    private Task OnEndDateChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { EndDate = DateTime.TryParse(Str(e.Value), out var d) ? d : null });

    private Task OnDescriptionChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { Description = Str(e.Value) });

    private Task ToggleCurrent(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        return OnEntryChanged.InvokeAsync(Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate });
    }
}

private string? ErrorMessage;
private bool IsValidating;

private static string Str(object? value) => value?.ToString() ?? string.Empty;
private void OnFullNameChanged(ChangeEventArgs e) => Model = Model with { FullName = Str(e.Value) };
private void OnEmailChanged(ChangeEventArgs e) => Model = Model with { Email = Str(e.Value) };
private void OnPhoneChanged(ChangeEventArgs e) => Model = Model with { Phone = Str(e.Value) };
private void OnAddressChanged(ChangeEventArgs e) => Model = Model with { Address = Str(e.Value) };

